function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
	var book_sys_id = g_form.getValue('related_book');
	console.log("book sys_id", book_sys_id);

		var ga = new GlideAjax('BookSearch');
		ga.addParam('sysparm_name', 'fetchBookDetails');
		ga.addParam('sysparm_book_sys_id', book_sys_id);
	   	ga.getXMLAnswer(populateBookDetails); 

		function populateBookDetails(response) {
			var bookData = JSON.parse(response);
			const bd = bookData.book_title;
			console.log("------", bd);
			//console.log("--------------", bookData);
		   //	g_form.setValue(book_title, bookData.boo)
		}


}

